# -*- coding: utf-8 -*-
"""Отчёт, часть 2: Similarweb (2.3), «сверху вниз» (2.4), «снизу вверх» и потенциальные клиенты (2.5)."""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import inputs as I
from assumptions import A
from rep_common import *

SW = "SW_объем_рынка_Similarweb_NotaCode.xlsx"
SV = "СВ_сверху_вниз_снизу_вверх_NotaCode.xlsx"
PK = "ПК_потенциальные_клиенты_NotaCode.xlsx"


def build(d: Doc):
    c = cite
    sw, sv, pk = R["sw"], R["sv"], R["pk"]
    osw = OUT["sw"]
    d.h(3, "2.3 Similarweb: выборка, доли, концентрация, каналы, география")
    d.h(4, "2.3.1 Бесплатный доступ и журнал ручной фиксации")
    d.add("Similarweb — источник оценочных данных, а не измеритель рынка; трафик конкурентов не равен продажам " + c("sw_method", "m_swb") + ". При бесплатном доступе методика выполняется вручную: открываются карточки сайтов, фиксируются видимые показатели, делаются снимки экрана, записываются дата и период. Массовые выгрузки (Data Exporter, API), глубокая история и детальные разбивки недоступны, поэтому любой количественный вывод даётся диапазоном, а показатель, который не показан, отмечается «нет данных в бесплатном доступе» и не домысливается.")
    d.add("Страница plantuml.com открыта 30.09.2026 (период «август 2026», график «последние 3 месяца», все типы трафика) " + c("sw_plantuml") + ". На страницах app.diagrams.net, mermaid.live и lucidchart.com бесплатный просмотр закрылся сообщением об исчерпании лимита поисков; ограничение не обходилось, значения по этим доменам в журнале отмечены «доступ закрыт». Имена файлов скриншотов построены по образцу М1 табл. 14 (similarweb_traffic_[домен]_[страна]_[период]).")
    rows = []
    for r in cells(SW, "08_Источники", "A14:F21"):
        rows.append([fv(r[0]), fv(r[1]), fv(r[2]), fv(r[3]), fv(r[4]), fv(r[5])])
    d.table("swlog", "Журнал ручной фиксации Similarweb (SWБ табл. 7), фрагмент",
            ["Дата", "Домен", "Раздел Similarweb", "Показатель", "Значение", "Комментарий / снимок экрана"], rows,
            note="Полный журнал — в приложении В. Период во всех строках — август 2026 (последние 3 месяца); требование М1 «не менее 12 месяцев» при бесплатном доступе выполнить нельзя — это ограничение расчёта, а не выполненное условие.")
    d.h(4, "2.3.2 Конкурентная выборка")
    d.add("Выборка составляет четыре домена, то есть меньше минимума методик (пять по М2 §5; целевой ориентир 10–20 по СВ §3). Причина — закрытие бесплатного просмотра после первых обращений; недостающие домены вынесены в перечень работ для выполнения вручную (приложение Б). Данные по plantuml.com сняты 30.09.2026 (снимок экрана низкого разрешения и текст страницы); визиты app.diagrams.net (7,8 млн) указаны в отчёте ЛР1, а значения eraser.io (678,5 тыс.) и mermaidchart.com («менее 20 тыс.», принята верхняя граница) получены при предварительном замере 17–23.09.2026 и в итоговый отчёт ЛР1 не вошли; повторный замер невозможен (лимит), поэтому эти значения считаются непроверенными, а влияние выборки оценено отдельно (таблица {T:swsens}). Состав выборки проверен на омонимию: все четыре домена — сайты инструментов диаграмм, омонимичных значений нет.")
    rows = []
    for dom, name, typ, visits, status, rel, q in I.SW_DOMAINS:
        rows.append([dom, name, typ, n(visits), status, n(rel, 2)])
    d.table("swsample", "Карточки сайтов выборки (М2 табл. 6, SWБ табл. 6)",
            ["Домен", "Название", "Тип", "Визиты в месяц (весь мир)", "Статус данных", "Доля релевантного трафика, Д-02"], rows,
            note="Доля релевантного трафика — экспертное допущение в диапазоне СЦ табл. 10 (20–75 %). Дополнительные показатели plantuml.com: глобальный ранг 93 517, ранг в России 24 334, ранг категории 692 (Programming and Developer Software), отказы 45,52 %, страниц за визит 3,18, длительность 3 мин 16 с; Россия 9,07 % трафика, Германия 7,21 %, Китай 6,4 %, Япония 4,61 %, США 4,57 %; Organic Search 48,47 %. Похожие сайты (affinity): app.diagrams.net 100 %, mermaidchart.com 92 %, eraser.io 90 %, drawio-app.com 85 %, sequencediagram.org 80 %, visual-paradigm.com 75 %, mermaid.live 68 %.")
    t2 = sw["two"]
    d.table("swsens", "Чувствительность к составу выборки: четыре домена и два домена, упомянутые в ЛР1",
            ["Показатель", "Четыре домена (основной расчёт)", "Два домена (plantuml.com, app.diagrams.net)"],
            [["Суммарный трафик, визитов в месяц (мир)", n(sum(x[3] for x in I.SW_DOMAINS)), n(t2["tam"])],
             ["Трафик Беларуси по допущению Д-01, визитов в месяц", n(sum(x[3] for x in I.SW_DOMAINS) * round(I.GEO_BY, 6), 0), n(t2["obs"], 0)],
             ["Объём рынка по SW-X, BYN в год (осторожный / базовый / оптимистичный)", rng3(sw["market_year"], 0), rng3(t2["market"], 0)],
             ["HHI", n(sw["hhi"], 0), n(t2["hhi"], 0)]],
            note="Исключение двух непроверенных значений уменьшает трафик выборки менее чем на 8 %, потому что доминирует app.diagrams.net; выводы о концентрации и объёме не меняются.")
    d.table("swtypes", "Типы сайтов выборки (SWБ табл. 5, М1 табл. 16)",
            ["Тип сайта", "Представлен в выборке", "Не представлен (🔲 ДОСНЯТЬ: Similarweb по доменам соответствующих типов, табл. {T:todo}, п. 1)"],
            [["Прямые конкурентные продукты", "plantuml.com, eraser.io, mermaidchart.com", "mermaid.live, creately.com, online.visual-paradigm.com, dbdiagram.io, structurizr.com, kroki.io, gleek.io, sequencediagram.org"],
             ["Заменители (универсальные редакторы)", "app.diagrams.net", "lucidchart.com, miro.com, excalidraw.com, whimsical.com"],
             ["Специализированные BPMN-инструменты", "—", "bpmn.io, staruml.io"],
             ["Контентные и справочные сайты", "—", "mermaid.js.org, учебные сайты по UML/BPMN"]])

    d.h(4, "2.3.3 Доли трафика, CR3, CR5 и HHI")
    shares = sw["shares"]
    tot_vis = sum(x[3] for x in I.SW_DOMAINS)
    rel_tot = sum(x[3] * x[5] for x in I.SW_DOMAINS)
    rows = []
    for dom, name, typ, visits, status, rel, q in I.SW_DOMAINS:
        s1 = visits / tot_vis
        s2 = visits * rel / rel_tot
        rows.append([dom, n(visits), pct(s1, 2), n((s1 * 100) ** 2, 1), pct(s2, 2), n((s2 * 100) ** 2, 1)])
    rows.append(["Сумма / HHI", n(tot_vis), "100 %", n(sw["hhi"], 0), "100 %", n(osw["hhi_rel2"], 0)])
    d.table("swshares", "Доли трафика выборки и слагаемые HHI (М1 ф. 2, М2 §7, §12)",
            ["Домен", "Визиты/мес.", "Доля по сырым визитам", "Слагаемое HHI (сырые)", "Доля по визитам с учётом релевантной доли (Д-02)", "Слагаемое HHI (с Д-02)"], rows,
            note="Доля по сырым визитам — формула М1 и SWБ §7; доля по релевантным визитам — подход М2 §7; подходы дают разные значения (W-6). Географическая доля Беларуси принята одинаковой для всех доменов, поэтому не влияет на доли.")
    d.table("hhi", "CR3, CR5, HHI и уровни концентрации (лист 09_Концентрация)",
            ["Показатель", "По сырым визитам", "По релевантным визитам (Д-02)"],
            [["CR3, %", n(sw["cr3"], 1), n(osw["cr3_rel2"], 1)],
             ["CR5, % (при четырёх доменах CR5 = 100 %)", n(sw["cr5"], 0), "100"],
             ["HHI = Σ (доля в %)²", n(sw["hhi"], 0), n(osw["hhi_rel2"], 0)],
             ["Уровень по шкале М2 табл. 16 (до 1 500 / 1 500–2 500 / выше 2 500)", "высокая", "высокая"],
             ["Проверка HHI ≥ CR3² / 3 (порог " + n(sw["hhi_min_check"], 0) + ")", "выполняется", "выполняется"]],
            note="Качественные уровни М1 табл. 10 чисел не содержат; по М1 концентрация также оценивается как высокая. Значения — оценка концентрации цифрового трафика выборки из четырёх доменов, а не выручки и не рыночной власти: доминирует универсальный редактор draw.io (86,6 % визитов). В шаблоне SW-X расчёта CR3/CR5/HHI нет — лист добавлен в рабочей копии (Р-42).")
    d.figure("swvis", "05_similarweb_vyborka_vizity.png", "Визиты доменов выборки Similarweb, в месяц (логарифмическая шкала; синий — подтверждено скриншотом)")
    d.figure("swhhi", "06_doli_trafika_CR3_HHI.png", "Доли доменов в суммарных визитах выборки")

    d.h(4, "2.3.4 Каналы, география и поисковые запросы")
    rows = []
    for r in cells(SW, "03_Каналы", "A4:H9"):
        rows.append([r[0], fv(r[1]), fv(r[2], 0), fv(r[3], 0), r[7]])
    d.table("swchan", "Лист 03_Каналы: канальная структура (только показанные значения)",
            ["Канал", "Средневзвешенная доля", "Трафик рынка, визитов/мес.", "Трафик рынка, визитов/год", "Приоритет"], rows,
            note="Бесплатная карточка plantuml.com показывает долю только Organic Search (48,47 %); Direct и Referrals названы вторым и третьим каналами без долей, Social, Paid, Mail и Display доли не показаны. Email/Mail в шаблоне колонки не имеет (Р-43) и фиксируется в журнале. Формула средневзвешенных долей в копии исправлена (П-18): делитель — сумма трафика только по строкам, где доля показана.")
    d.add("Географическая структура. Беларусь в топ-5 стран Similarweb не попадает; доля России у plantuml.com — 9,07 %. Доля Беларуси оценена как допущение Д-01: доля России по Similarweb, умноженная на отношение числа запросов Беларусь/Россия по запросу «plantuml» на вкладке «Регионы» Вордстата (170 / 7 874; скользящее окно 29.08.2026–27.09.2026, снято 30.09.2026), то есть " + n(I.GEO_BY * 100, 4) + " % визитов. Доля Минска — " + n(I.GEO_MINSK * 100, 4) + " % (Минск даёт 124 из 170 запросов Беларуси). Допущение единое для всех доменов выборки и является главным источником неопределённости: для универсального редактора draw.io реальная доля Беларуси может отличаться. Оговорки к Д-01: (1) доля России 9,07 % в Similarweb относится к desktop-трафику (на странице указано, что Россия — основная страна по desktop-трафику), а в расчёте применена ко всем визитам, включая мобильные; (2) отношение 170 / 7 874 из Вордстата отражает только пользователей Яндекса, а доля Яндекса в поиске в Беларуси и России различается. Направление возможного смещения по имеющимся данным определить нельзя, поэтому оценка Д-01 остаётся допущением с низкой надёжностью (🔲 ДОСНЯТЬ: доля Беларуси по plantuml.com и другим доменам в Similarweb, табл. {T:todo}, п. 1–2).")
    d.table("wsreg", "Вордстат, вкладка «Регионы», запрос «plantuml», окно 29.08.2026–27.09.2026 (снято 30.09.2026)",
            ["Регион", "Запросов", "Индекс интереса, %"],
            [["Россия", "7 874", "103,04"], ["СНГ (исключая Россию)", "340", "106,72"], ["Беларусь", "170", "118,12"], ["Казахстан", "154", "138,85"], ["Минск и область", "142", "205,29"], ["Минск", "124", "255,54"]])
    rows = []
    for r in cells(SW, "04_География", "A4:J7"):
        rows.append([r[0], pct(r[1], 4), fv(r[2], 1), fv(r[3], 0), fv(r[8], 0), fv(r[9], 0)])
    d.table("swgeo", "Лист 04_География: шаблонный расчёт и корректный вариант (П-10)",
            ["Территория", "Доля трафика", "Шаблон: трафик, мес. (C)", "Шаблон: трафик, год (D)", "Корректно: трафик до сужения × доля, мес. (I)", "Корректно, год (J)"], rows,
            note="Шаблон умножает долю территории на B12 — трафик, уже суженный до Беларуси, то есть применяет географию дважды (П-10); корректный вариант умножает на трафик до географического сужения. Россия — гипотеза расширения, в итог не входит (В-6). Приоритет территорий по порогам шаблона (≥ 0,35 / ≥ 0,15) для малых долей всегда «низкий» и в выводах не используется.")
    rows = []
    for r in cells(SW, "05_Запросы", "A4:K10"):
        rows.append([r[0], fv(r[2]), fv(r[3], 0), r[4], fv(r[5], 1), fv(r[6], 0), fv(r[10], 0), r[8]])
    d.table("swq", "Лист 05_Запросы: типы намерений и индекс коммерческого интереса (П-11)",
            ["Запрос", "Доля среди запросов", "Трафик рынка по шаблону, мес. (D)", "Тип намерения", "Вес", "Индекс (G)", "Корректно: D × доля Organic (K)", "Решение"], rows,
            note="Доли Similarweb по запросам в бесплатном доступе не показаны (для plantuml.com видны только названия: plantuml, plant uml, plantuml online, plantuml editor, planuml; всего 866 ключевых слов), поэтому доли рассчитаны по частотности Вордстата среди перечисленных запросов. Шаблон умножает долю запроса на весь трафик рынка, а не на его поисковую часть, что вероятно завышает оценку (П-11); в столбце K — вариант с долей Organic. Веса SW-X (проблемный 0,6; информационный 0,1) отличаются от ПС табл. 9 (проблемный 0,30–0,60) — Р-44.")

    d.table("swcpc", "Поисковые запросы plantuml.com с оценкой CPC (М1 табл. 19)", ["Ключевое слово", "Тип", "CPC, USD", "Комментарий"],
            [["plantuml", "брендовый", "1,24", "Similarweb, desktop, весь мир, 30.09.2026"],
             ["plant uml", "брендовый", "1,46", ""], ["plantuml online", "брендовый + инструмент", "1,39", ""],
             ["plantuml editor", "брендовый + инструмент", "1,22", ""], ["planuml", "брендовый (опечатка)", "0,53", ""],
             ["прочие 861 ключевых слов", "нет данных в бесплатном доступе", "—", "Всего 866 ключевых слов; Organic 100 %, Paid 0 %"]],
            note="Все показанные ключевые слова брендовые, поэтому вывод о небрендовом (категорийном) спросе по Similarweb сделать нельзя; стоимость клика 0,5–1,5 USD указывает на коммерческую ценность запросов для рекламодателей, при этом доля платного трафика у plantuml.com нулевая.")
    d.h(4, "2.3.5 Расчёт объёма по SW-X")
    d.table("swp1", "Лист 01_Параметры: значения до и после исправления формул (П-1)",
            ["Показатель", "В шаблоне (суммирование с 5-й строки)", "В рабочей копии"],
            [["Количество конкурентов в выборке", "4", n(cell(SW, "01_Параметры", "B8"))],
             ["Наблюдаемый релевантный трафик, мес.", n(osw["p1_before"], 1), n(cell(SW, "01_Параметры", "B9"), 1)],
             ["Наблюдаемый релевантный трафик, год", n(osw["p1_before"] * 12, 1), n(cell(SW, "01_Параметры", "B10"), 1)],
             ["Оценка всего цифрового трафика рынка, мес. (покрытие 0,7)", n(osw["p1_before"] / 0.7, 1), n(cell(SW, "01_Параметры", "B12"), 1)],
             ["Оценка всего цифрового трафика рынка, год", n(osw["p1_before"] / 0.7 * 12, 1), n(cell(SW, "01_Параметры", "B13"), 1)]],
            note="В шаблоне B9 = SUM(G5:G24) и B10 = SUM(H5:H24) при данных с 4-й строки: первый конкурент (здесь plantuml.com) теряется. В копии диапазоны исправлены на G4:G23 и H4:H23.")
    rows = []
    for r in cells(SW, "06_Воронка_сценарии", "A5:J7"):
        rows.append([r[0], n(r[1], 2), n(r[2], 0), pct(r[3], 2), pct(r[4], 0), n(r[5], 2), n(r[6], 0), n(r[7], 2), n(r[8], 0), n(r[9], 0)])
    d.table("swfun", "Лист 06_Воронка_сценарии: рыночный объём по сценариям",
            ["Сценарий", "Покрытие", "Трафик рынка, визитов/мес.", "CR1", "CR2", "Чек, BYN", "Оплат на клиента в год", "Заказов/мес.", "Выручка/мес., BYN", "Выручка/год, BYN"], rows,
            note="Покрытие (0,8 / 0,7 / 0,55), CR1 (0,8 / 1,5 / 2,5 %) и достижимая доля — значения шаблона (Р-37, Р-39). CR2 — допущение проекта (Free → Pro 3–5 %); чек — 40 USD в год (осторожный и базовый сценарии) и медиана тарифов конкурентов. Трафик рынка — только географически суженные визиты выборки (Беларусь), без доли релевантного (SW-X её не содержит, Р-38).")
    rows = []
    for r in cells(SW, "06_Воронка_сценарии", "A12:D14"):
        rows.append([r[0], n(r[1], 0), pct(r[2], 1), n(r[3], 1)])
    d.table("swsom", "Достижимая доля нового бизнеса (SOM) по SW-X",
            ["Сценарий", "Рыночная выручка/год, BYN", "Достижимая доля", "Выручка нового бизнеса/год, BYN"], rows,
            note="Итог листа: объём цифрового рынка оценивается от " + n(sw["market_year"][0], 0) + " до " + n(sw["market_year"][2], 0) + " BYN в год, достижимая выручка — от " + n(sw["som"][0], 0) + " до " + n(sw["som"][2], 0) + " BYN в год.")

    d.h(4, "2.3.6 TAM, SAM, SOM цифрового внимания (М1) и вариант по М2")
    rows = []
    for r in cells(SW, "10_TAM_SAM_SOM_М1", "A3:B17"):
        v = r[1]
        rows.append([r[0], pct(v, 4) if isinstance(v, float) and v < 0.01 and "Доля" in r[0] else (pct(v, 2) if isinstance(v, float) and v < 1 else (n(v, 0) if abs(v) >= 1000 else n(v, 1)))])
    d.table("m1tam", "Модель М1 табл. 22: TAM / SAM / SOM цифрового внимания (базовый сценарий)", ["Элемент", "Значение"], rows,
            note="TAM — суммарный трафик четырёх сайтов; SAM по географии — доля Беларуси; SAM по каналу — доля Organic одного домена (остальные доли не показаны); SOM по выручке — трафик × достижимая доля × CR1 × CR2 × чек × 12. Проверка поиском — лист 05_Запросы.")
    rows = []
